<div class="page-head"><div><h1>Subscribers</h1><p class="muted">Emails collected by popups and the newsletter block, with GDPR consent records.</p></div><div class="page-actions"><a class="btn btn-ghost btn-sm" href="?export=csv"><?= icon('download', 16) ?> Export CSV</a></div></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Email</th><th>Consent</th><th>Source</th><th>Subscribed</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($subs as $s): ?><tr><td><?= e($s['email']) ?></td><td title="<?= e($s['consent_text']) ?>"><?= $s['consent'] ? 'Yes' : 'No' ?></td><td><?= e($s['source']) ?></td><td class="small"><?= e(fmt_date($s['created_at'], true)) ?></td><td><?= $s['unsubscribed_at'] ? '<span class="badge badge-muted">Unsubscribed</span>' : '<span class="badge badge-ok">Active</span>' ?></td>
<td><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $s['id'] ?>"><?php if (!$s['unsubscribed_at']): ?><button class="btn btn-xs btn-ghost" name="act" value="unsubscribe">Unsubscribe</button><?php endif ?> <button class="btn btn-xs btn-link" name="act" value="delete" data-confirm="Permanently delete this subscriber (GDPR erasure)?">Delete</button></form></td></tr><?php endforeach ?>
<?php if (!$subs): ?><tr><td colspan="6" class="empty-cell">No subscribers yet.</td></tr><?php endif ?>
</tbody></table></div><?= pager_html($pg, '/admin/subscribers/') ?>
